56: function applyTransform(mesh: THREE.Mesh, transform: TransformDescriptor, size: Vec3): void {
57:   mesh.position.set(transform.position.x, transform.position.y, transform.position.z);
58:   const rotation = transform.rotation;
59:   if (rotation) {
60:     mesh.quaternion.set(rotation.x, rotation.y, rotation.z, rotation.w);
61:   }
62:   const scale = transform.scale ?? UNIT_SCALE;
63:   mesh.scale.set(size.x * scale.x, size.y * scale.y, size.z * scale.z);
64: }
