66: /** Turns a hole descriptor into renderable meshes backed by shared geometry and material caches. */
67: export class HoleSceneBuilder {
68:   private readonly boxGeometry: THREE.BoxGeometry;
69:   private readonly cylinderGeometry: THREE.CylinderGeometry;
70:   private readonly materials: Map<string, THREE.MeshStandardMaterial>;
71: 
72:   constructor() {
73:     this.boxGeometry = new THREE.BoxGeometry(1, 1, 1);
74:     this.cylinderGeometry = new THREE.CylinderGeometry(0.5, 0.5, 1, 24);
75:     this.materials = new Map();
76:   }
77: 
78:   build(hole: Hole): HoleSceneResult {
79:     const group = new THREE.Group();
80:     group.name = hole.id;
81: 
82:     for (const surface of hole.surfaces) {
83:       group.add(this.buildSurface(surface));
84:     }
85:     for (const obstacle of hole.obstacles) {
86:       group.add(this.buildObstacle(obstacle));
87:     }
88:     group.add(this.buildCup(hole));
89: 
90:     return {
91:       group,
92:       meshCount: group.children.length,
93:       dispose: () => {
94:         group.clear();
95:       },
96:     };
97:   }
98: 
99:   dispose(): void {
100:     this.boxGeometry.dispose();
101:     this.cylinderGeometry.dispose();
102:     for (const material of this.materials.values()) {
103:       material.dispose();
104:     }
105:     this.materials.clear();
106:   }
107: 
108:   private buildSurface(surface: SurfaceDescriptor): THREE.Mesh {
109:     const geometry = surface.shape === 'cylinder' ? this.cylinderGeometry : this.boxGeometry;
110:     const mesh = new THREE.Mesh(
111:       geometry,
112:       this.materialFor('surface:' + surface.material, SURFACE_COLORS[surface.material]),
113:     );
114:     mesh.name = surface.id;
115:     applyTransform(mesh, surface.transform, surface.size);
116:     mesh.castShadow = false;
117:     mesh.receiveShadow = true;
118:     return mesh;
119:   }
120: 
121:   private buildObstacle(obstacle: ObstacleDescriptor): THREE.Mesh {
122:     const geometry = obstacle.type === 'pillar' ? this.cylinderGeometry : this.boxGeometry;
123:     const mesh = new THREE.Mesh(
124:       geometry,
125:       this.materialFor('obstacle:' + obstacle.type, OBSTACLE_COLORS[obstacle.type]),
126:     );
127:     mesh.name = obstacle.id;
128:     applyTransform(mesh, obstacle.transform, obstacle.size);
129:     mesh.castShadow = true;
130:     mesh.visible = obstacle.enabled !== false;
131:     return mesh;
132:   }
133: 
134:   private buildCup(hole: Hole): THREE.Mesh {
135:     const mesh = new THREE.Mesh(this.cylinderGeometry, this.materialFor('cup', CUP_COLOR));
136:     mesh.name = hole.id + '-cup';
137:     const diameter = hole.cup.radius * 2;
138:     mesh.position.set(hole.cup.position.x, hole.cup.position.y, hole.cup.position.z);
139:     mesh.scale.set(diameter, hole.cup.radius, diameter);
140:     mesh.castShadow = false;
141:     mesh.receiveShadow = true;
142:     return mesh;
143:   }
