145:   private materialFor(key: string, color: number): THREE.MeshStandardMaterial {
146:     const cached = this.materials.get(key);
147:     if (cached) {
148:       return cached;
149:     }
150:     const material = new THREE.MeshStandardMaterial({ color, roughness: 0.85, metalness: 0.05 });
151:     material.name = key;
152:     this.materials.set(key, material);
153:     return material;
154:   }
155: }
